<section class="confirmation panel"><p class="eyebrow">Customer account</p><h1>Create your account</h1><p class="muted">Save your contact details and see your order history.</p><?php if($error): ?><div class="store-error" role="alert"><?= e($error) ?></div><?php endif; ?><form method="post" class="checkout-form" style="text-align:left"><?= $csrf->field() ?><label>Full name<input name="name" required maxlength="190" autocomplete="name" value="<?= e_attr($input['name']??'') ?>"></label><label>Email address<input type="email" name="email" required maxlength="190" autocomplete="email" value="<?= e_attr($input['email']??'') ?>"></label><label>Phone number<input name="phone" maxlength="60" autocomplete="tel" value="<?= e_attr($input['phone']??'') ?>"></label><label>Password<input type="password" name="password" required minlength="12" autocomplete="new-password"><small class="muted">At least 12 characters with upper and lowercase letters and a number.</small></label><label>Confirm password<input type="password" name="password_confirmation" required minlength="12" autocomplete="new-password"></label><button class="btn">Create account</button></form><p>Already registered? <a href="<?= e_attr($basePath) ?>/account/login">Sign in</a></p></section>
